// The one shared connection to the database. The server's database code imports `prisma` from here.
// New to Prisma? See docs/help/prisma.md

import { PrismaPg } from '@prisma/adapter-pg';
// Generated by `prisma generate` (plain JavaScript, so it runs the same on laptops and on Vercel).
import { PrismaClient } from './generated/prisma/index.js';
import config from './config.js';

const adapter = new PrismaPg({ connectionString: config.databaseUrl });

const prisma = new PrismaClient({ adapter });

export default prisma;
